/// Requirement: FieldBoundary { field: "Q", value: 0, boundary: Min }
/// 8-bit / byte size
#[test]
fn test_aarch32_vcadd_a1_a_field_q_0_min_800_fc800800() {
    // Encoding: 0xFC800800
    // Test aarch32_VCADD_A1_A field Q = 0 (Min)
    // ISET: A32
    // Fields: Vd=0, Vn=0, Vm=0, N=0, D=0, M=0, rot=0, S=0, Q=0
    let encoding: u32 = 0xFC800800;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

