/// Requirement: FieldBoundary { field: "imm6", value: 32, boundary: PowerOfTwo }
/// power of 2 (2^5 = 32)
#[test]
fn test_aarch32_vsli_t1a1_a_field_imm6_32_poweroftwo_510_f3a00510() {
    // Encoding: 0xF3A00510
    // Test aarch32_VSLI_T1A1_A field imm6 = 32 (PowerOfTwo)
    // ISET: A32
    // Fields: D=0, Vd=0, L=0, Q=0, M=0, Vm=0, imm6=32
    let encoding: u32 = 0xF3A00510;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

