/// Provenance: aarch32_VFNMA_A1_A
/// ASL: `field cond 28 +: 4`
/// Requirement: FieldBoundary { field: "cond", value: 2, boundary: PowerOfTwo }
/// condition CS/HS (carry set)
#[test]
fn test_aarch32_vfnma_a1_a_field_cond_2_poweroftwo_800_2e900800() {
    // Encoding: 0x2E900800
    // Test aarch32_VFNMA_A1_A field cond = 2 (PowerOfTwo)
    // ISET: A32
    // Fields: M=0, N=0, Vm=0, D=0, Vn=0, size=0, op=0, cond=2, Vd=0
    let encoding: u32 = 0x2E900800;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

