/// Requirement: FieldBoundary { field: "op", value: 3, boundary: Max }
/// maximum value (3)
#[test]
fn test_aarch32_vqmovn_t1a1_a_field_op_3_max_200_f3b202c0() {
    // Encoding: 0xF3B202C0
    // Test aarch32_VQMOVN_T1A1_A field op = 3 (Max)
    // ISET: A32
    // Fields: op=3, size=0, M=0, Vm=0, Vd=0, D=0
    let encoding: u32 = 0xF3B202C0;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

