/// Requirement: FieldBoundary { field: "size", value: 2, boundary: PowerOfTwo }
/// 32-bit / word size
#[test]
fn test_aarch32_vshl_r_t1a1_a_field_size_2_poweroftwo_400_ef200400() {
    // Thumb encoding (32): 0xEF200400
    // Test aarch32_VSHL_r_T1A1_A field size = 2 (PowerOfTwo)
    // ISET: T32
    // Fields: size=2, D=0, Q=0, Vn=0, U=0, M=0, Vd=0, Vm=0, N=0
    let mut cpu = create_thumb_cpu();
    let encoding: u32 = 0xEF200400;
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "T32 instruction should execute successfully"
    );
}

