/// Requirement: FieldBoundary { field: "N", value: 1, boundary: Max }
/// maximum value (1)
#[test]
fn test_aarch32_vqshl_r_t1a1_a_field_n_1_max_410_f2000490() {
    // Encoding: 0xF2000490
    // Test aarch32_VQSHL_r_T1A1_A field N = 1 (Max)
    // ISET: A32
    // Fields: D=0, M=0, U=0, Vm=0, Vd=0, N=1, Q=0, Vn=0, size=0
    let encoding: u32 = 0xF2000490;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

