/// Requirement: FieldBoundary { field: "imm4", value: 7, boundary: PowerOfTwoMinusOne }
/// immediate midpoint (7)
#[test]
fn test_aarch32_vbic_i_t1a1_a_field_imm4_7_poweroftwominusone_130_ef800037() {
    // Thumb encoding (32): 0xEF800037
    // Test aarch32_VBIC_i_T1A1_A field imm4 = 7 (PowerOfTwoMinusOne)
    // ISET: T32
    // Fields: imm4=7, Vd=0, D=0, Q=0, imm3=0, cmode=0, i=0
    let mut cpu = create_thumb_cpu();
    let encoding: u32 = 0xEF800037;
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "T32 instruction should execute successfully"
    );
}

