/// Requirement: FieldSpecial { field: "size", value: 1, meaning: "Size variant 1" }
/// Size variant 1
#[test]
fn test_aarch32_vmvn_r_t1a1_a_special_size_1_size_variant_1_1408_f3b40580() {
    // Encoding: 0xF3B40580
    // Test aarch32_VMVN_r_T1A1_A special value size = 1 (Size variant 1)
    // ISET: A32
    // Fields: Vd=0, Q=0, D=0, M=0, Vm=0, size=1
    let encoding: u32 = 0xF3B40580;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

